import os
from typing import List, Dict, Any, Optional

import requests


class TextContentSafety:
    """
    Flags or redacts unsafe spans from text using Azure AI Content Safety.

    Requires:
      - AZURE_AI_CONTENT_SAFETY_ENDPOINT
      - AZURE_AI_CONTENT_SAFETY_KEY

    Endpoint example:
      https://<your-resource-name>.cognitiveservices.azure.com
    """

    def __init__(
        self,
        endpoint: Optional[str] = None,
        api_key: Optional[str] = None,
        api_version: str = "2024-09-01",
        severity_threshold: int = 2,
        timeout: float = 30.0,
    ):
        self.endpoint = (endpoint or os.getenv("AZURE_AI_CONTENT_SAFETY_ENDPOINT") or "").rstrip("/")
        self.api_key = api_key or os.getenv("AZURE_AI_CONTENT_SAFETY_KEY") or os.getenv("AZURE_AI_CONTENT_SAFETY_API_KEY")
        self.api_version = api_version
        self.severity_threshold = severity_threshold
        self.timeout = timeout

        if not self.endpoint:
            raise ValueError("Missing Azure AI Content Safety endpoint.")
        if not self.api_key:
            raise ValueError("Missing Azure AI Content Safety API key.")

    def _analyze(self, text: str) -> Dict[str, Any]:
        url = f"{self.endpoint}/contentsafety/text:analyze?api-version={self.api_version}"
        headers = {
            "Ocp-Apim-Subscription-Key": self.api_key,
            "Content-Type": "application/json",
        }
        payload = {
            "text": text,
            "categories": ["Hate", "SelfHarm", "Sexual", "Violence"],
            "outputType": "FourSeverityLevels",
        }
        resp = requests.post(url, headers=headers, json=payload, timeout=self.timeout)
        resp.raise_for_status()
        return resp.json()

    @staticmethod
    def _merge_spans(spans: List[Dict[str, int]]) -> List[Dict[str, int]]:
        if not spans:
            return []
        spans = sorted(spans, key=lambda s: (s["offset"], s["offset"] + s["length"]))
        merged = [dict(spans[0])]
        for s in spans[1:]:
            last = merged[-1]
            last_end = last["offset"] + last["length"]
            cur_end = s["offset"] + s["length"]
            if s["offset"] <= last_end:
                last["length"] = max(last_end, cur_end) - last["offset"]
            else:
                merged.append(dict(s))
        return merged

    def flag_unsafe_spans(self, text: str) -> List[Dict[str, Any]]:
        """
        Returns a list of unsafe spans:
          [
            {"offset": 10, "length": 5, "text": ".....", "category": "Violence", "severity": 3},
            ...
          ]
        """
        result = self._analyze(text)
        spans: List[Dict[str, Any]] = []

        categories = result.get("categoriesAnalysis") or result.get("categories_analysis") or []
        for item in categories:
            severity = int(item.get("severity", 0))
            if severity < self.severity_threshold:
                continue
            span_info = item.get("span")
            if not span_info:
                continue
            offset = int(span_info.get("offset", 0))
            length = int(span_info.get("length", 0))
            spans.append(
                {
                    "offset": offset,
                    "length": length,
                    "text": text[offset : offset + length],
                    "category": item.get("category", item.get("name", "unknown")),
                    "severity": severity,
                }
            )

        # Optional prompt/PII-like annotations can be handled here if returned by the API.
        return spans

    def redact_unsafe_spans(self, text: str, replacement: str = "[REDACTED]") -> str:
        spans = self.flag_unsafe_spans(text)
        if not spans:
            return text

        merged = self._merge_spans([{"offset": s["offset"], "length": s["length"]} for s in spans])
        pieces = []
        cursor = 0

        for span in merged:
            start = max(0, span["offset"])
            end = max(start, span["offset"] + span["length"])
            pieces.append(text[cursor:start])
            pieces.append(replacement)
            cursor = end

        pieces.append(text[cursor:])
        return "".join(pieces)


def flag_unsafe_spans(text: str) -> List[Dict[str, Any]]:
    return TextContentSafety().flag_unsafe_spans(text)


def redact_unsafe_spans(text: str, replacement: str = "[REDACTED]") -> str:
    return TextContentSafety().redact_unsafe_spans(text, replacement)
